/**
 * Markdown helpers shared by every game-wiki page module.
 *
 * Nothing here knows about a game system. Values are shown with the SDK's own formatters,
 * which the caller passes in, so a number on the wiki reads the way the SDK prints it.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    pageName, cell, table, infobox, bullets, titleCase, sampleLevels, sections (+3 more)
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

/**
 * A GitHub wiki page name is its filename, and here it is also a link target.
 *
 * Stricter than the rule in `build-wiki.mjs` for that reason: a game name can hold `(`, `)`
 * or `%`, and a parenthesis ends a Markdown link early, leaving it pointing at half a name.
 */
export function pageName(title) {
  return title
    .replace(/\+/g, ' Plus ')
    .replace(/[^\p{L}\p{N}\s.-]/gu, '')
    .trim()
    .replace(/[\s-]+/g, '-')
}

/** Make a value safe inside a table cell: pipes and line breaks end a cell otherwise. */
export function cell(value) {
  if (value === null || value === undefined || value === '') return '—'
  return String(value).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ').trim() || '—'
}

export function table(header, rows) {
  if (rows.length === 0) return '_No rows._'
  const line = cells => `| ${cells.map(cell).join(' | ')} |`
  return [line(header), `| ${header.map(() => '---').join(' | ')} |`, ...rows.map(line)].join('\n')
}

/** The two-column summary box a wiki page opens with. Empty values are dropped. */
export function infobox(pairs) {
  const rows = pairs.filter(([, value]) => value !== null && value !== undefined && value !== '')
  if (rows.length === 0) return ''
  // A header row is required for a table to render; this one is deliberately blank.
  return ['|  |  |', '| --- | --- |', ...rows.map(([label, value]) => `| **${cell(label)}** | ${cell(value)} |`)].join('\n')
}

export function bullets(items) {
  return items.filter(Boolean).map(item => `- ${String(item).replace(/\r?\n/g, ' ')}`).join('\n')
}

/** `camelCase` or `snake_case` field name to a column heading. */
export function titleCase(key) {
  return String(key)
    .replace(/_/g, ' ')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/^./, first => first.toUpperCase())
}

/**
 * Which rows of a long level table to show.
 *
 * A workshop stat has up to 6,001 levels. Every level up to `fullUntil` is kept, then every
 * `step`th, and always the last, so the top of the track is never cut off.
 */
export function sampleLevels(count, { fullUntil = 100, step = 100, showAllUpTo = 300 } = {}) {
  const all = Array.from({ length: count }, (_, index) => index)
  if (count <= showAllUpTo) return { indexes: all, sampled: false }
  const indexes = all.filter(index => index <= fullUntil || index % step === 0 || index === count - 1)
  return { indexes, sampled: true }
}

/** Join page sections, dropping the empty ones. */
export function sections(...parts) {
  return parts.filter(part => part !== null && part !== undefined && part !== '').join('\n\n')
}

export function heading(level, text) {
  return `${'#'.repeat(level)} ${text}`
}

/** Number formatting built on the SDK formatters handed in by the generator. */
export function createFormat(formatting) {
  const { formatCompact } = formatting

  /** A game value: compact above a million, otherwise trimmed of float noise. */
  function value(input) {
    if (typeof input !== 'number') return input
    if (!Number.isFinite(input)) return '—'
    if (Math.abs(input) >= 1e6) return formatCompact(input)
    // Six significant digits drops the float noise the game's own tables carry (1.049999952).
    return input.toLocaleString('en-US', { maximumSignificantDigits: 6 })
  }

  /** A cost. Zero is shown as a dash, since a zero in a cost column means "nothing to pay". */
  function cost(input) {
    if (typeof input !== 'number') return input
    return input === 0 ? '—' : value(input)
  }

  const percent = fraction => `${Number((fraction * 100).toPrecision(6))}%`

  return { value, cost, percent }
}

/**
 * A table straight from an array of records: one column per field, in field order.
 *
 * `columns` picks and orders fields, and may rename one: `['tier', ['coinBonus', 'Coin Bonus']]`.
 */
export function recordTable(rows, format, columns) {
  if (rows.length === 0) return '_No rows._'
  const picked = (columns ?? Object.keys(rows[0])).map(column => (Array.isArray(column) ? column : [column, titleCase(column)]))
  const show = input => {
    if (Array.isArray(input)) return input.map(show).join(', ')
    if (typeof input === 'boolean') return input ? 'Yes' : 'No'
    if (input && typeof input === 'object') return Object.entries(input).map(([key, item]) => `${titleCase(key)}: ${show(item)}`).join('; ')
    return format.value(input)
  }
  return table(picked.map(([, label]) => label), rows.map(row => picked.map(([key]) => show(row[key]))))
}
